WITH scored AS (SELECT *, SUM(cost) OVER w_part AS running_sum_cost, COUNT(cost) OVER w_part AS running_count_cost, MIN(cost) OVER w_part AS running_min_cost, MAX(cost) OVER w_part AS running_max_cost FROM shipments WHERE YEAR(shipped_date) = 2023 WINDOW w_part AS (PARTITION BY status ORDER BY delivered_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT carrier, COUNT(*) FILTER (WHERE carrier = 'DHL') AS dhl_rows, COUNT(*) FILTER (WHERE carrier = 'DHL') AS dhl_rows_2, SORT_ARRAY(COLLECT_SET(carrier)) AS carrier_list FROM scored GROUP BY carrier HAVING COUNT(*) FILTER (WHERE carrier = 'DHL') > 1 ORDER BY carrier DESC NULLS LAST;
